const req = (packID, addrs) => ({dsID:"www.hc-system.com.RemoteMonitor", reqType:"query", packID:String(packID), queryAddr:addrs});
const blocks = [
  req(1000, ['isMoving','curAlarm','curMode','curCycle','lastCycle','curAccount','origin','RemoteCmdLen']),
  req(1001, Array.from({length:8}, (_,i)=>`axis-${i}`)),
  req(1002, Array.from({length:8}, (_,i)=>`world-${i}`)),
  req(1003, Array.from({length:8}, (_,i)=>`curTorque-${i}`)),
  req(1004, Array.from({length:8}, (_,i)=>`curSpeed-${i}`)),
  req(1005, Array.from({length:50}, (_,i)=>`Addr-${800+i}`)),
  req(1006, Array.from({length:40}, (_,i)=>`Addr-${850+i}`)),
  req(1007, ['input-0']),
  req(1008, ['output-0']),
  req(1009, ['M-0']),
  req(1010, ['counter-0', 'counter-1', 'counter-2'])
];
const cycleId = (flow.get('cycleId')||0) + 1; flow.set('cycleId', cycleId);
msg.payload = blocks.map(b=>({cycle:cycleId, req:b}));
return msg;

// --- helpers ---
function bitsToDict(n, prefix) {
  const bits = (Number(n) >>> 0).toString(2).padStart(32, '0').split('').reverse();
  const out = {}; let i = 0;
  for (let r = 1; r <= 4; r++) {
    for (let c = 0; c < 8; c++) {
      out[`${prefix}${r}${c}`] = Number(bits[i++] || 0);
    }
  }
  return out;
}

function toObj(x) {
  if (x == null) return null;
  if (typeof x === 'string') {
    try { return JSON.parse(x); }
    catch (e) { node.warn("No es JSON válido (preview): " + x.slice(0, 120)); return null; }
  }
  if (typeof x === 'object') return x;
  return null;
}

// --- normaliza la entrada: array de 11 items (string u objeto) ---
const list = Array.isArray(msg.payload) ? msg.payload : [msg.payload];

// indexa por packID
const byId = {};
for (const it of list) {
  const o = toObj(it);
  if (!o) continue;
  const id = String(o.packID ?? (o.req && o.req.packID) ?? "");
  if (!id) continue;
  byId[id] = o;
}

// accesores seguros: devolvemos [] si no hay queryData
const byPack = (id) => {
  const o = byId[String(id)] || {};
  return Array.isArray(o.queryData) ? o.queryData : [];
};

function getQD(o){ return (o && Array.isArray(o.queryData)) ? o.queryData : []; }
function unpackCounter(o){
  const qd = getQD(o);
  const c = Array.isArray(qd) && qd[0];
  if (!Array.isArray(c) || c.length < 3) return null;
  return { id: Number(c[0]), target: Number(c[1]), current: Number(c[2]), mode: 2 };
}

// extrae cada bloque
const b0 = byPack(1000);           // isMoving, curAlarm, curMode, ...
const axis = byPack(1001);
const world = byPack(1002);
const torque = byPack(1003);
const speed = byPack(1004);
const addrA = byPack(1005);           // 800..849 (50)
const addrB = byPack(1006);           // 851..889 (39)  (saltamos 850)
const x0 = (byPack(1007)[0] || 0);
const y0 = (byPack(1008)[0] || 0);
const m0 = (byPack(1009)[0] || 0);

// counters
const countersArr = getQD(byId['1010']);           // p.ej. [[0,40,17],[1,2,1],[2,1000,35]]
const counters = {};
const counters_summary = [];
for (const c of countersArr){
  if (Array.isArray(c) && c.length >= 3){
    const id = Number(c[0]), target = Number(c[1]), current = Number(c[2]);
    counters[`counter-${id}`] = { id, target, current, mode: 2 };
    counters_summary.push(id);
  }
}

// direcciones
const addrKeys = [...Array(50)].map((_, i) => String(800 + i))
  .concat([...Array(40)].map((_, i) => String(850 + i)));
const addrVals = [...addrA, ...addrB];
const addresses = {};
addrKeys.forEach((k, i) => addresses[k] = Number(addrVals[i] || 0));

// construir payload final
msg.payload = {
  robot_id: flow.get('robot_id') || "01",
  ip: env.get('ROBOT_HOST') || msg.host || null,
  online: true,
  status: {
    order_id: null,
    addresses,
    outputs: {
      x: bitsToDict(x0, 'x'),
      y: bitsToDict(y0, 'y'),
      m: bitsToDict(m0, 'm'),
      euy: {}
    },
    status: {
      movement_status: [Number(b0[0] || 0)],
      alarm_code: [Number(b0[1] || 0)],
      cur_mode: [Number(b0[2] || 0)],
      current_cycle_time: [Number(b0[3] || 0)],
      last_cycle_time: [Number(b0[4] || 0)],
      cur_account: [Number(b0[5] || 0)],
      homed: [Number(b0[6] || 0)],
      axis_position: (axis || []).map(Number),
      world_position: (world || []).map(Number),
      axis_torque: (torque || []).map(Number),
      axis_velocity: (speed || []).map(Number)
    },
    counters
  },
  timestamp: new Date().toISOString()
};

// validación útil: avisa si llegaron requests (queryAddr) en vez de respuestas (queryData)
for (const id of [1000, 1001, 1002, 1003, 1004, 1005, 1006, 1007, 1008, 1009, 1010]) {
  const o = byId[String(id)];
  if (o && !Array.isArray(o.queryData) && Array.isArray(o.queryAddr)) {
    node.warn(`Pack ${id}: llegó queryAddr (parece TX), no queryData (RX). Revisa que el Join esté conectado al lado de respuesta.`);
  }
}


const state_ini = Number(b0[6] || 0) === 1;   
const outY = msg.payload.status.outputs.y;    
const alarm = msg.payload?.status?.status?.alarm_code?.[0] ?? 0;
const axisPos = msg.payload.status.status.world_position || [];
const lastPos = axisPos.slice(0, 3);

msg.payload = JSON.stringify(msg.payload);

global.set("robot_last_pos", lastPos);
global.set("robot_flags", {
  state_ini: state_ini,
  state_end: Number(outY?.y33 || 0), 
  y30: Number(outY?.y30 || 0),
  y33: Number(outY?.y33 || 0),
  alarm: Number(alarm)//,
  //process: Number(addresses["850"])
});

//node.warn(addresses);
//node.warn(lastPos);

return msg;

let q = flow.get('pending') || [];
const {cycle, req} = msg.payload;
q.push({cycle, req});
flow.set('pending', q);

msg.payload = JSON.stringify(req);    
msg.action  = "write";                
msg.host    = env.get('ROBOT_HOST');
msg.port    = Number(env.get('ROBOT_PORT'));
msg.cycle   = cycle;                   
return msg;

const ROBOT_ID = env.get('ROBOT_ID') || '01';
const HOST = env.get('ROBOT_HOST');
const PORT = Number(env.get('ROBOT_PORT') || 9760);

const VEL_TEST = 100;
const VEL_PROD = 200;

function nextPack() {
    const n = (flow.get('packSeq') || 900000) + 1;
    flow.set('packSeq', n);
    return String(n);
}
const cmdFrame = (a, pid) => ({ dsID: "www.hc-system.com.RemoteMonitor", reqType: "command", packID: pid, cmdData: a.map(String) });
const wr1 = (addr, val) => cmdFrame(["rewriteData", String(addr), String(val), "0"], nextPack());
const wrList = (start, arr) => cmdFrame(["rewriteDataList", String(start), arr.length, 0, ...arr.map(Number)].map(String), nextPack());

function yIndex(y) {
    y = Number(y);
    if (10 <= y && y <= 17) return y - 10;
    if (20 <= y && y <= 27) return y - 12;
    if (30 <= y && y <= 37) return y - 14;
    if (40 <= y && y <= 47) return y - 16;
    throw new Error("indice invalido");
}
const mm = v => Math.trunc(Number(v) * 1000);

const cmd = msg.payload || {};
const name = cmd.name;
const p = cmd.params || {};
const corr = String(cmd.corr || ((flow.get('corrSeq') || 0) + 1));
flow.set('corrSeq', Number(corr));
const order_id = cmd.order_id || null;

let frames = [];

// ===================== COMANDOS =====================
switch (name) {
    case "start_button":
        global.set("robot_process", {
            process: 1
        });
        cmdFrame(["modifyOutput", 0, yIndex(31), 0], nextPack())
        frames.push(wr1(850, 1));   
        frames.push(cmdFrame(["modifyGSPD", VEL_PROD], nextPack()));
        frames.push(cmdFrame(["startButton"], nextPack()));
        break;
    case "pause_button":
        const current_state = global.get("fsm")?.state || null;
        const is_running = global.get("fsm")?.state_running || false;
        const value = p.value; // valor del botón, true o false

        if (value === true && (current_state === "Running" || is_running === true)) {
            frames.push(cmdFrame(["actionPause"], nextPack()));
        } else if (value === false && current_state === "Paused") {
            frames.push(cmdFrame(["startButton"], nextPack()));
        }
        break;
    case "stop_button":
        frames.push(cmdFrame(["stopButton"], nextPack()));
        break;
    case "action_stop":
        frames.push(cmdFrame(["actionStop"], nextPack()));
        break;
    case "clear_alarm_button":
        frames.push(cmdFrame(["stopButton"], nextPack()));
        break;
    case "cancel_button":
        [30, 32, 33, 35, 36, 45].forEach(y => frames.push(cmdFrame(["modifyOutput", 0, yIndex(y), 0], nextPack())));
        frames.push(wr1(855, 0));
        frames.push(cmdFrame(["actionStop"], nextPack()));
        break;
    case "modify_output_y":
        frames.push(cmdFrame(["modifyOutput", 0, yIndex(p.output_id), Number(!!p.value)]), nextPack());
        break;
    case "modify_counter":
        frames.push(cmdFrame([
            "modifyCounter",
            String(p.counter_id),
            String(p.current),
            String(p.target)
        ], nextPack()));
        break;
    case "modify_global_velocity":
        frames.push(cmdFrame(["modifyGSPD", Number(p.velocity)], nextPack()));
        break;
    case "write_data_single":
        frames.push(wr1(p.address, p.value));
        break;
    case "write_data_block": {
        const data = Array.isArray(p.data) ? p.data.map(Number) : [];
        frames.push(cmdFrame(["rewriteDataList", Number(p.start_address), data.length, Number(p.permanent ?? 0), ...data], nextPack()));
        break;
    }
}

// ===================== PROCESOS =====================
if (name === "proceso_01") {
    // Args esperados en p: pick[], put[], cantidad_z, cantidad_x, dz_p, dz_n, dz_pick, espesor, ancho, bit_coordinador, bit_compensacion, compenzacion_desfase
    const pick = (p.pick || []).map(mm);
    const put = (p.put || []).map(mm);
    const up = [0, 0, mm(p.dz_p || 0), 0, 0, 0];
    const down = [0, 0, mm(p.dz_n || 0), 0, 0, 0];
    const pick_up = [0, 0, mm(p.dz_pick || 0), 0, 0, 0];

    const compensacion_x = Number(p.cantidad_x || 0) * Number(p.ancho || 0);

    frames.push(wr1(850, 1));
    frames.push(wr1(855, 0));

    frames.push(wrList(800, pick));
    frames.push(wrList(810, put));
    frames.push(wrList(830, up));
    frames.push(wrList(840, down));
    frames.push(wrList(860, pick_up));

    const cfg820 = [
        Number(p.cantidad_z || 0),
        Number(p.cantidad_x || 0),
        mm(p.dz_p || 0), mm(p.dz_n || 0),
        mm(p.espesor || 0), mm(p.ancho || 0),
        mm(p.dz_pick || 0),
        Number(p.bit_coordinador || 0),
        mm(compensacion_x || 0)
    ];
    frames.push(cmdFrame(["rewriteDataList", 820, cfg820.length, 0, ...cfg820], nextPack()));

    // Bloque 851 (bit_compensacion, compenzacion_desfase*1000)
    frames.push(cmdFrame(["rewriteDataList", 851, 2, 0, Number(p.bit_compensacion || 0), mm(p.compenzacion_desfase || 0)], nextPack()));
}

if (name === "proceso_02" || name === "proceso_03" || name === "proceso_04" || name === "proceso_06") {
    const code = Number(name.slice(-2)); // 2,3,4,6
    global.set("robot_process", {
        process: code
    });
    frames.push(wr1(850, code));
    frames.push(cmdFrame(["actionStop"], nextPack()));
    frames.push(cmdFrame(["modifyGSPD", VEL_TEST], nextPack()));
    frames.push(cmdFrame(["modifyOutput", 0, yIndex(45), 0], nextPack())); // Y45 OFF
    frames.push(cmdFrame(["startButton"], nextPack()));
}

if (name === "proceso_05") {
    global.set("robot_process", {
        process: 5
    });
    const lastWorld = global.get('robot_last_pos') || []; 
    node.warn(lastWorld);
    const world_z = Number(lastWorld[2] || 0);
    const high = 1500;
    let compensacion_z = high - world_z;
    if (compensacion_z < 1) {compensacion_z = 0;}
    frames.push(cmdFrame(["actionStop"], nextPack()));
    frames.push(wr1(850, 5));
    frames.push(cmdFrame(["modifyGSPD", VEL_TEST], nextPack()));
    frames.push(wr1(870, 0));
    frames.push(wr1(871, 0));
    frames.push(wr1(872, mm(compensacion_z)));
    frames.push(cmdFrame(["startButton"], nextPack()));
    frames.push(cmdFrame(["modifyGSPD", VEL_TEST], nextPack()));
    frames.push(cmdFrame(["modifyOutput", 0, yIndex(45), 0], nextPack())); // Y45 OFF
}

const pids = frames.map(f => f.packID);
let p2c = flow.get('pack2corr') || {};
let agg = flow.get('rpcAgg') || {};
pids.forEach(pid => p2c[pid] = corr);
agg[corr] = { expected: new Set(pids), collected: [], name, order_id, started: Date.now() };
flow.set('pack2corr', p2c);
flow.set('rpcAgg', agg);

msg.payload = frames.map(f => (JSON.stringify(f)));
msg.action = "write";
msg.host = HOST;
msg.port = PORT;
return msg;

// ====== FSM con timer interno ======
const STATE_KEY = "process:state";

let fsm= global.get("fsm") || { state: "Vacio", awaiting_clean: false, clean_time: 0 };
const rob = global.get("robot_flags") || { state_ini: false, y30: 0, y33: 0, process: 0 };
const proc = global.get("robot_process") || {process: 0};

const p = msg.payload || {};
const cmdReply = Array.isArray(p.cmdReply) ? p.cmdReply : [];
const cmd = cmdReply[0] || null;
const result = cmdReply[1] === "ok";

const setState = (s) => { fsm.state = s; global.set("fsm", fsm); };

// --- limpiar timer previo si existe (evita duplicados) ---
let tId = context.get('cleanTimer');
function clearCleanTimer() {
    if (tId) { clearTimeout(tId); context.set('cleanTimer', null); }
}


node.warn(proc);

// --- Transiciones por comando ---
if (cmd) {
    switch (cmd) {
        case "startButton":
            clearCleanTimer();
            fsm.awaiting_clean = false;
            fsm.clean_time = 0;
            node.warn(rob.process);
            if (proc.process === 1) {
                setState("Running");
            }
            break;

        case "actionPause":
            clearCleanTimer();
            fsm.awaiting_clean = false;
            fsm.clean_time = 0;
            if (result === true) setState("Paused");
            else if (result === false && rob.state_ini) setState("Running");
            else if (result === false && !rob.state_ini) setState("Vacio");
            break;

        case "stopButton":
            clearCleanTimer();
            setState("Stopped");
            fsm.awaiting_clean = true;
            fsm.clean_time = Date.now() + 4000; // 4 s

            // Agenda el vaciado para dentro de 4 s
            tId = setTimeout(() => {
                setState("Vacio");
                // Publica a Redis even if no more msgs arrive
                //node.send({ topic: STATE_KEY, payload: fsm.state });
            }, 4000);
            context.set('cleanTimer', tId);
            break;

        case "resume_proceso_01":
            clearCleanTimer();
            fsm.awaiting_clean = false;
            fsm.clean_time = 0;
            setState("Running");
            break;
    }
}

// Terminación por salidas: y10 & y33 → Terminated
if (rob.y33 === 1) {
    clearCleanTimer();
    fsm.awaiting_clean = false;
    fsm.clean_time = 0;
    setState("Terminated");
}

if (rob.alarm != 0) {
    clearCleanTimer();
    fsm.awaiting_clean = false;
    fsm.clean_time = 0;
    setState("Stopped");
}

// if (fsm.state === "Stopped" && rob.alarm === 0) {
//     setState("Vacio");
// }

global.set("fsm", fsm);

// Publica el estado actual a Redis (para SET)
msg.topic = STATE_KEY;
msg.payload = fsm.state;
msg.cmd = cmd;
msg.result = result;
msg.alarm = rob.alarm;
return msg;
